sealed class UiState {
    data class Success(val value: Int) : UiState()
    data class Failure(val reason: String) : UiState()
    object Loading : UiState()
}

fun show(s: UiState): String = when (s) {
    is UiState.Success -> "ok ${s.value}"
    is UiState.Failure -> "error ${s.reason}"
    UiState.Loading -> "loading"
}

fun main() {
    println(show(UiState.Success(5)))
    println(show(UiState.Failure("boom")))
    println(show(UiState.Loading))
}

sealed interface Shape
data class Circle(val r: Double) : Shape
data class Rect(val w: Double, val h: Double) : Shape

fun area(s: Shape): Double = when (s) {
    is Circle -> 3.0 * s.r * s.r
    is Rect -> s.w * s.h
}

fun main() {
    println(area(Circle(2.0)))
    println(area(Rect(2.0, 3.5)))
}

