fun <T> firstOrFallback(items: List<T>, fallback: T): T =
    if (items.isEmpty()) fallback else items[0]

class Box<T>(val value: T) {
    fun show(): String = "Box($value)"
}

fun main() {
    println(firstOrFallback(listOf(5, 6), 0))
    println(firstOrFallback(emptyList<String>(), "none"))
    println(Box("hi").show())
    println(Box(3.5).show())
}

