fun operate(a: Int, b: Int, op: (Int, Int) -> Int): Int = op(a, b)

fun compose(f: (Int) -> Int, g: (Int) -> Int): (Int) -> Int = { x -> g(f(x)) }

fun main() {
    println(operate(6, 3) { x, y -> x * y })
    println(operate(6, 3) { x, y -> x + y })
    val inc = { x: Int -> x + 1 }
    val dbl = { x: Int -> x * 2 }
    println(compose(inc, dbl)(5))
    println(listOf(1, 2, 3).map(compose(dbl, inc)))
}

